import { profile as p } from "../data/profile.js";
import { boot, pageHero, scene, lazyScene } from "./shared.js";
import { heading, esc, interestCards } from "../components/utils.js";
import { timeline } from "../components/timeline.js";
import { init as initTimeline } from "../animations/timeline.js";
const polar = p.diagrams.polarization,
  cma = p.diagrams.cma;
boot(
  "research",
  `
  ${pageHero("research", `${scene("polarization", polar.aria)}<div class="interactive-controls">${polar.modes.map((mode, i) => `<button class="segmented-button" data-polarization="${i}" aria-pressed="${i === 1}">${mode}</button>`).join("")}<span class="readout" data-ar>${polar.ar} 0.0 ${polar.units}</span></div><p class="diagram-caption mono">${polar.caption}</p>`)}
  <section class="container"><div class="current-card"><div><p class="eyebrow">${p.research.currentLabel}</p><h2>${p.research.currentTitle}</h2></div><p>${p.research.currentDescription}</p></div></section>
  <section class="section container">${heading(p.research.experienceEyebrow, p.research.experienceTitle)}${timeline(p.experience)}<div class="specs">${p.research.specs.map((s) => `<span class="spec-chip">${esc(s)}</span>`).join("")}</div></section>
  <section class="section cma-section"><div class="container">${heading(p.research.cmaEyebrow, p.research.cmaTitle)}<p class="cma-intro">${p.research.cmaDescription}</p><div class="cma-display">${scene("cma", cma.aria)}<div class="interactive-controls cma-controls">${[...cma.modes, cma.combine].map((m, i) => `<button class="segmented-button" data-mode="${i}" aria-pressed="${i === 0}">${m}</button>`).join("")}</div><p class="diagram-hint">${cma.hint}</p><p class="diagram-caption mono">${cma.caption}</p></div></div></section>
  <section class="section container">${heading(p.research.interestsEyebrow, p.research.interestsTitle)}<div class="interests-grid research-interests">${interestCards(true)}</div></section>
`,
);
lazyScene(
  "polarization",
  () => import("../animations/polarization.js"),
  "polarization",
);
lazyScene("cma", () => import("../animations/cma.js"), "cma");
initTimeline(document.querySelector("main"), {
  enabled: p.animations.timeline,
});
